dbPath := newTempDB(t)
bus, err := eventbus.New(dbPath)
if err != nil { t.Fatalf("New: %v", err) }
e := &eventbus.Event{Type: "task.status_changed", Source: "orchestrator", Details: "{}"}
if err := bus.Publish(e); err != nil { t.Fatalf("Publish: %v", err) }
if err := bus.Deliver(e.ID, "watcher-agent"); err != nil { t.Fatalf("Deliver: %v", err) }

events, err := bus.UnackedDeliveries("watcher-agent")
if err != nil { t.Fatalf("UnackedDeliveries: %v", err) }
if len(events) != 1 { t.Fatalf("got %d events, want 1", len(events)) }
if events[0].ID != e.ID { t.Errorf("event ID = %q, want %q", events[0].ID, e.ID) }
